R.append((7242909,
("Burritos de desayuno", "Desayune sobre la marcha con estos burritos. Puede rellenarlos con todo tipo de ingredientes y simplemente enrollarlos en papel encerado.", "8", "220 g",
 ["8 tortillas integrales", "salsa de chile y sazonador (opcional)", "2 jitomates grandes, picados", "1 pimiento rojo, en rodajas", "4 cebollines, picados", "100 g de espinaca cocida o congelada descongelada, escurrida", "1 aguacate, pelado y en rebanadas", "80 g de queso cheddar, rallado", "1 lata de 400 g de frijoles, escurridos", "4 huevos revueltos"],
 ["Prepare los rellenos fríos y tenga cocidos y calientes los rellenos calientes.", "Coloque las tortillas apiladas en una sartén seca a fuego bajo y voltéelas con frecuencia para que cada lado se caliente sin tostarse. Caliente un lado de la tortilla en contacto directo con la sartén y luego pásela a la parte superior de la pila. Repita para que todas las tortillas se calienten. No las deje crujientes por fuera: necesitan ser fáciles de doblar, pero puede dorarlas hasta que queden crujientes una vez dobladas, si lo desea.", "Extienda las tortillas y agregue unos cuantos ingredientes cubriendo la mitad inferior de cada tortilla.", "Espolvoree un poco de queso cheddar y salsa de chile o sazonador (si los usa), luego enrolle, doblando hacia dentro los lados.", "Coloque los burritos enrollados en una sartén seca a fuego bajo, con la unión hacia abajo. Cocine un par de minutos, volteándolos un par de veces para que se cocinen de manera uniforme."],
 ["También puede agregar papa cocida en cubitos, camote o champiñones.", "O quienes no sean vegetarianos pueden agregar un poco de pescado a la parrilla o ahumado.", "Porciones de fruta/verdura por porción: 1"], []),
("بوريتو الإفطار", "تناول إفطارك أثناء التنقل مع هذه البوريتو. يمكنك حشوها بجميع أنواع المكونات ولفّها ببساطة بورق مقاوم للدهن.", "8", "220 غ",
 ["8 خبز تورتيلا من القمح الكامل", "صلصة فلفل حار وتوابل (اختياري)", "2 حبة طماطم كبيرة، مفرومة", "1 فلفل رومي أحمر، مقطع إلى شرائح", "4 بصلات خضراء، مفرومة", "100 غ سبانخ مطبوخة أو مجمدة ومذابة، مصفّاة", "1 أفوكادو، مقشر ومقطع إلى شرائح", "80 غ جبن شيدر، مبشور", "1 علبة بحجم 400 غ من الفاصوليا، مصفّاة", "4 بيضات مخفوقة (بيض مخفوق)"],
 ["حضّر الحشوات الباردة وأبقِ الحشوات الساخنة مطبوخة ودافئة.", "ضع التورتيلا فوق بعضها في مقلاة جافة على نار هادئة، وقلّبها باستمرار بحيث يدفأ كل جانب دون أن يتحمّص. سخّن أحد جانبي التورتيلا بتلامس مباشر مع المقلاة ثم انقلها إلى أعلى الكومة. كرّر العملية حتى تدفأ جميع التورتيلات. لا تجعل الخارج مقرمشًا، فهي تحتاج إلى أن تكون سهلة الطي، لكن يمكنك تقريمشها بعد طيّها إن رغبت.", "افرد التورتيلات ثم أضف بعض المكونات لتغطية النصف السفلي من كل تورتيلا.", "رشّ قليلًا من جبن الشيدر وصلصة الفلفل الحار أو التوابل (إن استخدمتها) ثم لفّها مع طي الجانبين إلى الداخل.", "ضع التورتيلات الملفوفة في مقلاة جافة على نار هادئة، مع جعل خط الالتحام إلى الأسفل. اطهها لمدة دقيقتين مع تقليبها مرتين لتنضج بالتساوي."],
 ["يمكنك أيضًا إضافة بطاطس مطبوخة مقطعة إلى مكعبات أو بطاطا حلوة أو فطر.", "أو يمكن لغير النباتيين إضافة بعض السمك المشوي أو المدخن.", "حصص الفاكهة/الخضار لكل حصة: 1"], []),
))
R.append((7247191,
("Risotto de mariscos", "Una versión más baja en grasa de un risotto clásico, que sigue siendo cremosa y suculenta.", "3", "554 g",
 ["1 cucharadita de aceite de colza", "1 cebolla, picada fina", "1 cubito de caldo de verduras bajo en sal, disuelto en 900 ml de agua", "1 pimiento amarillo, picado fino", "1 diente de ajo, machacado", "una buena pizca de pimienta blanca", "15 g de perejil, picado fino, más 1 cucharada para servir", "150 g de arroz Arborio (para risotto)", "1 filete grueso de salmón (de unos 125 g), en cubos y sin piel", "100 g de camarones cocidos y pelados", "50 g de anillos de calamar", "50 g de yogur natural bajo en grasa", "un molido de pimienta negra", "una pizca de perejil recién picado"],
 ["Caliente el aceite en una olla y cocine la cebolla 5 minutos.", "En otra olla, caliente el caldo, a fuego lento suave, y manténgalo a fuego muy bajo.", "Agregue a la cebolla el pimiento amarillo, el ajo, la pimienta blanca y la mitad del perejil, revuelva 1 minuto y agregue el arroz. Revuelva 2 minutos, luego agregue dos cucharones de caldo, lo suficiente para apenas cubrir el arroz, y revuelva.", "Revolviendo el arroz con frecuencia, agregue el caldo caliente poco a poco, de modo que el arroz quede apenas cubierto. El risotto debe burbujear muy suavemente.", "Después de 20 minutos, agregue el caldo restante y el salmón. Revuelva otros 3 minutos, agregue los camarones y el calamar, cocine 2 minutos y luego pruebe el arroz para asegurarse de que esté «al dente» (ligeramente firme) y de que el salmón esté perfectamente cocido.", "Por último, incorpore enérgicamente el perejil restante y el yogur, tape y deje reposar 2 minutos. Espolvoree con pimienta negra y perejil antes de servir."],
 ["Puede usar camarones y calamares congelados y descongelados.", "Mantenga el caldo a fuego lento en una olla aparte, para que esté caliente cuando lo agregue al arroz y no baje la temperatura ni detenga la cocción del arroz. Agréguelo poco a poco; si se le acaba, agregue un poco de agua hirviendo.", "Revolver con frecuencia, con una cuchara de madera, hace que el arroz libere su almidón y asegura una textura cremosa.", "Porciones de fruta/verdura por porción: 1"], []),
("ريزوتو المأكولات البحرية", "نسخة أقل دهونًا من الريزوتو الكلاسيكي، لكنها ما زالت كريمية وشهية.", "3", "554 غ",
 ["1 ملعقة صغيرة زيت اللفت (كانولا)", "1 بصلة، مفرومة ناعمًا", "1 مكعب مرق خضار قليل الملح، مذاب في 900 مل ماء", "1 فلفل رومي أصفر، مفروم ناعمًا", "1 فص ثوم، مهروس", "رشة كبيرة من الفلفل الأبيض", "15 غ بقدونس، مفروم ناعمًا، بالإضافة إلى 1 ملعقة كبيرة للتقديم", "150 غ أرز أربوريو (أرز الريزوتو)", "1 شريحة سلمون (حوالي 125 غ)، مقطعة إلى مكعبات ومنزوعة الجلد", "100 غ روبيان مطبوخ ومقشر", "50 غ حلقات حبار", "50 غ زبادي طبيعي قليل الدسم", "قليل من الفلفل الأسود المطحون", "رشة بقدونس مفروم طازج"],
 ["سخّن الزيت في قدر واطه البصل لمدة 5 دقائق.", "في قدر منفصل، سخّن المرق على نار هادئة بلطف وأبقه على حرارة منخفضة جدًا.", "أضف الفلفل الرومي الأصفر والثوم والفلفل الأبيض ونصف كمية البقدونس إلى البصل، وحرّك لمدة دقيقة وأضف الأرز. حرّك لمدة دقيقتين، ثم أضف مغرفتين من المرق، بكمية تكفي لتغطية الأرز فقط، وحرّك.", "مع تحريك الأرز باستمرار، أضف المرق الساخن شيئًا فشيئًا بحيث يكون الأرز مغطى بالكاد. يجب أن يغلي الريزوتو بلطف شديد.", "بعد 20 دقيقة، أضف ما تبقى من المرق والسلمون. حرّك 3 دقائق أخرى، ثم أضف الروبيان والحبار، واطه لمدة دقيقتين، ثم تذوّق الأرز للتأكد من أنه ناضج «آل دنتي» (متماسك قليلًا) ومن نضج السلمون تمامًا.", "وأخيرًا، حرّك بقوة البقدونس المتبقي والزبادي، وغطِّه واتركه يستقر لمدة دقيقتين. رشّ الفلفل الأسود والبقدونس قبل التقديم."],
 ["يمكنك استخدام الروبيان والحبار المجمدين بعد إذابتهما.", "أبقِ المرق يغلي بلطف في قدر منفصل ليكون ساخنًا عند إضافته إلى الأرز فلا يخفض الحرارة ويوقف نضج الأرز. أضفه قليلًا قليلًا؛ وإذا نفد المرق فأضف قليلًا من الماء المغلي.", "التحريك المنتظم بملعقة خشبية يجعل الأرز يطلق نشاه ويضمن قوامًا كريميًا.", "حصص الفاكهة/الخضار لكل حصة: 1"], []),
))
R.append((7247269,
("Pastel de chocolate con frutas en charola", "Un postre que gusta a toda la familia y que puede servirse tibio o frío.", "12", "40 g",
 ["2 cucharaditas de aceite de colza", "1 plátano grande, partido y cortado en trozos (150 g)", "100 g de arándanos azules", "50 g de azúcar", "50 g de harina integral", "2 cucharaditas colmadas de cacao en polvo", "1 cucharadita de polvo para hornear", "1 cucharadita de extracto de vainilla", "50 ml de aceite de colza", "50 ml de leche semidescremada (más si es necesario)"],
 ["Engrase con el aceite un molde para pastel de 20 x 25 cm y precaliente el horno a 180 °C (gas 4).", "Esparza de manera uniforme los trozos de plátano y los arándanos sobre el fondo del molde.", "Ponga en un tazón el azúcar, la harina integral, el cacao en polvo y el polvo para hornear, y mezcle bien.", "Agregue al tazón el extracto de vainilla, el aceite de colza y la leche, y mezcle de nuevo.", "Si la masa del pastel está demasiado espesa, agregue poco a poco pequeñas cantidades de leche hasta que quede con una consistencia tersa y vertible.", "Vierta de manera uniforme sobre el plátano y los arándanos, y hornee de 15 a 20 minutos. Está listo cuando un cuchillo insertado en el centro sale limpio."],
 ["Puede usar cualquier combinación de frutas, como peras, zarzamoras o frambuesas, o frutas secas como pasas, pasas sultanas o ciruelas pasas.", "Si no tiene frutos rojos frescos, también sirve la fruta congelada descongelada; solo escurra el jugo.", "Para una versión sin gluten, use la misma cantidad (50 g) en lugar de la harina de trigo integral; quizá necesite agregar una o dos cucharadas más de leche (las harinas sin gluten suelen absorber más humedad que el trigo), o use 50 g de almendras molidas y agregue 30 g de harina sin gluten.", "Sirva tibio con un poco de crema fresca, o frío como pastel.", "También funciona con un molde redondo de 23 cm."], []),
("كعكة الشوكولاتة بالفاكهة في صينية", "حلوى ترضي جميع أفراد الأسرة، ويمكن تقديمها دافئة أو باردة.", "12", "40 غ",
 ["2 ملعقة صغيرة زيت اللفت (كانولا)", "1 موزة كبيرة، مشقوقة ومقطعة إلى قطع (150 غ)", "100 غ توت أزرق", "50 غ سكر", "50 غ دقيق القمح الكامل", "2 ملعقة صغيرة مكوّمة مسحوق كاكاو", "1 ملعقة صغيرة بيكنج باودر", "1 ملعقة صغيرة خلاصة فانيليا", "50 مل زيت اللفت (كانولا)", "50 مل حليب نصف خالي الدسم (والمزيد عند الحاجة)"],
 ["ادهن قالب كعك مقاس 20 × 25 سم بالزيت وسخّن الفرن مسبقًا إلى 180° مئوية (درجة الغاز 4).", "انثر قطع الموز والتوت الأزرق بالتساوي على قاع القالب.", "ضع السكر ودقيق القمح الكامل ومسحوق الكاكاو والبيكنج باودر في وعاء وامزجها جيدًا.", "أضف خلاصة الفانيليا وزيت اللفت والحليب إلى الوعاء وامزج مرة أخرى.", "إذا كان خليط الكعكة كثيفًا جدًا، فأضف كميات صغيرة من الحليب تدريجيًا حتى يصبح قوامه ناعمًا وسهل الصب.", "اسكبه بالتساوي فوق الموز والتوت الأزرق، واخبزه لمدة 15-20 دقيقة. تكون الكعكة جاهزة عندما يخرج السكين نظيفًا بعد غرزه في الوسط."],
 ["يمكنك استخدام أي مزيج من الفواكه، مثل الكمثرى أو التوت الأسود أو توت العليق، أو فواكه مجففة مثل الزبيب أو زبيب السلطانة أو البرقوق المجفف.", "إذا لم يتوفر لديك توت طازج، فالفاكهة المجمدة بعد إذابتها تفي بالغرض أيضًا، فقط تخلّص من العصير.", "للحصول على نسخة خالية من الغلوتين، استخدم الكمية نفسها (50 غ) بدلًا من دقيق القمح الكامل، وقد تحتاج إلى إضافة ملعقة كبيرة أو ملعقتين إضافيتين من الحليب (الدقيق الخالي من الغلوتين يمتص رطوبة أكثر من القمح)، أو استخدم 50 غ من اللوز المطحون وأضف 30 غ من الدقيق الخالي من الغلوتين.", "قدّمها دافئة مع قليل من الكريمة الطازجة، أو باردة ككعكة.", "تنجح الوصفة أيضًا في قالب كعك دائري مقاس 23 سم."], []),
))
R.append((7247412,
("Sopa de cebolla a la francesa", "Esta reconfortante sopa de cebollas caramelizadas es suave y dulce, coronada con crotones crujientes.", "4", "590 g",
 ["3 cucharaditas de aceite de girasol", "1 kg de cebollas, picadas finas", "400 g de camote (cortado en 12 gajos)", "1 cubito de caldo de verduras bajo en sal, disuelto en 800 ml de agua hirviendo", "4 rebanadas de pan integral (30 g cada una)", "20 g de queso cheddar añejo reducido en grasa", "20 g de mozzarella", "1 cucharada de perejil fresco, picado fino, más un poco para servir", "una buena pizca de pimienta", "1 cucharadita de salsa de soya baja en sodio"],
 ["Precaliente el horno a 190 °C (gas 5). Ponga 2 cucharaditas del aceite en una olla, luego agregue las cebollas y cocine a fuego muy bajo de 30 a 40 minutos, revolviendo con frecuencia para que las cebollas se caramelicen.", "Mientras las cebollas se caramelizan, ponga el aceite restante en una charola para hornear. Agregue el camote y revuelva hasta que quede cubierto, luego hornee de 30 a 40 minutos.", "Agregue el caldo a las cebollas, deje que hierva y cocine a fuego lento 5 minutos.", "Mientras tanto, para hacer los crotones con queso: Corte cada rebanada de pan por la mitad y gratine, luego voltee y cubra cada una con el queso cheddar y la mozzarella, y gratine de nuevo hasta que el queso se derrita y se dore. También puede poner el pan cubierto con queso en una charola para hornear y cocinarlo en el horno de 5 a 10 minutos.", "Incorpore a la sopa el perejil, la pimienta y la salsa de soya, y luego sirva en cuatro tazones. Sirva con los crotones con queso y un poco de perejil fresco espolvoreado encima, y los gajos de camote a un lado."],
 ["Porciones de fruta/verdura por porción: 4"], []),
("حساء البصل الفرنسي", "هذا الحساء المريح بالبصل المكرمل ناعم النكهة وحلو، يُزيَّن بقطع الخبز المحمص المقرمشة.", "4", "590 غ",
 ["3 ملعقة صغيرة زيت دوار الشمس", "1 كغ بصل، مفروم ناعمًا", "400 غ بطاطا حلوة (مقطعة إلى 12 شريحة)", "1 مكعب مرق خضار قليل الملح، مذاب في 800 مل ماء مغلي", "4 شرائح خبز القمح الكامل (30 غ للشريحة)", "20 غ جبن شيدر معتّق مخفض الدسم", "20 غ موزاريلا", "1 ملعقة كبيرة بقدونس طازج، مفروم ناعمًا، بالإضافة إلى المزيد للتقديم", "رشة كبيرة من الفلفل", "1 ملعقة صغيرة صلصة صويا قليلة الملح"],
 ["سخّن الفرن مسبقًا إلى 190° مئوية (درجة الغاز 5). ضع 2 ملعقة صغيرة من الزيت في قدر، ثم أضف البصل واطهه على نار هادئة جدًا لمدة 30-40 دقيقة مع التحريك باستمرار حتى يتكرمل البصل.", "أثناء تكرمل البصل، ضع بقية الزيت على صينية خبز. أضف البطاطا الحلوة وقلّبها حتى تتغلّف بالزيت، ثم اخبزها في الفرن لمدة 30-40 دقيقة.", "أضف المرق إلى البصل، واتركه يغلي ثم اتركه على نار هادئة لمدة 5 دقائق.", "في هذه الأثناء، لتحضير قطع الخبز المحمص بالجبن: اقطع كل شريحة خبز إلى نصفين وحمّصها في الشواية، ثم اقلبها وضع على كل منها جبن الشيدر والموزاريلا، وحمّصها مرة أخرى حتى يذوب الجبن ويتحمّر. وبدلًا من ذلك، يمكنك وضع الخبز المغطى بالجبن على صينية خبز وطهيه في الفرن لمدة 5-10 دقائق.", "حرّك البقدونس والفلفل وصلصة الصويا في الحساء، ثم اسكبه في أربعة أوعية. قدّمه مع قطع الخبز المحمص بالجبن ورشة من البقدونس الطازج فوقه، وشرائح البطاطا الحلوة على الجانب."],
 ["حصص الفاكهة/الخضار لكل حصة: 4"], []),
))
R.append((7249160,
("Chips de plátano macho", "Cambie una bolsa de papas fritas por esta botana más saludable y deliciosa.", "4", "162 g",
 ["4 jitomates maduros, sin piel ni semillas", "1 cebolla morada pequeña, picada fina", "2 rodajas de piña de lata en su jugo, picadas finas", "1 chile rojo, sin semillas y picado fino", "2 cucharadas de cilantro fresco picado", "jugo de limón verde recién exprimido", "½ cucharadita de sazonador jerk", "2 plátanos machos verdes medianos", "2 cucharaditas de aceite de girasol", "½ cucharadita de sal de ajo", "½ cucharadita de ajo granulado", "½ cucharadita de pimienta negra", "una pizca de cayena (opcional)"],
 ["Precaliente el horno a 190 °C (170 °C con ventilador, gas 5). Forre una charola grande para hornear con papel para hornear antiadherente.", "Aplaste la mitad de los jitomates con un tenedor y páselos a un tazón. Pique en trozos grandes los jitomates restantes y agréguelos al tazón con la cebolla morada, la piña, el chile, el cilantro, el jugo de limón al gusto y el sazonador jerk. Mezcle bien hasta integrar. Refrigere 20 minutos para que se mezclen los sabores.", "Pele los plátanos machos y córtelos en rodajas de 1/8 de pulgada de grosor. Mézclelos con el aceite, el ajo granulado y la pimienta negra, y extiéndalos en una sola capa sobre la charola preparada.", "Hornee de 15 a 18 minutos, hasta que estén completamente horneados y cocidos. Deje enfriar y espolvoree con la pimienta de cayena, si lo desea."],
 ["Porciones de fruta/verdura por porción: 1"], []),
("شرائح الموز اللاتيني (البلانتين)", "استبدل كيس رقائق البطاطس بهذه الوجبة الخفيفة الأكثر صحة واللذيذة.", "4", "162 غ",
 ["4 حبات طماطم ناضجة، منزوعة القشر والبذور", "1 بصلة حمراء صغيرة، مفرومة ناعمًا", "2 حلقة أناناس معلب في عصيره، مفرومة ناعمًا", "1 فلفل أحمر حار، منزوع البذور ومفروم ناعمًا", "2 ملعقة كبيرة كزبرة خضراء طازجة مفرومة", "عصير ليمون أخضر معصور طازجًا", "½ ملعقة صغيرة توابل جيرك", "2 حبة موز لاتيني (بلانتين) أخضر متوسط الحجم", "2 ملعقة صغيرة زيت دوار الشمس", "½ ملعقة صغيرة ملح الثوم", "½ ملعقة صغيرة ثوم محبّب", "½ ملعقة صغيرة فلفل أسود", "رشة فلفل كايين (اختياري)"],
 ["سخّن الفرن مسبقًا إلى 190° مئوية (170° مئوية للفرن بالمروحة، درجة الغاز 5). بطّن صينية خبز كبيرة بورق خبز غير لاصق.", "اهرس نصف الطماطم بالشوكة وضعها في وعاء بالملعقة. افرم بقية الطماطم فرمًا خشنًا وأضفها إلى الوعاء مع البصل الأحمر والأناناس والفلفل الحار والكزبرة وعصير الليمون الأخضر حسب الذوق وتوابل جيرك. حرّك جيدًا حتى تمتزج. برّده لمدة 20 دقيقة لتنضج النكهات.", "قشّر الموز اللاتيني وقطّعه إلى شرائح بسماكة ⅛ بوصة. قلّبه مع الزيت والثوم المحبّب والفلفل الأسود، وافرده في طبقة واحدة على الصينية المجهّزة.", "اخبزه لمدة 15-18 دقيقة حتى ينضج تمامًا. اتركه يبرد ورشّ عليه فلفل الكايين إن رغبت."],
 ["حصص الفاكهة/الخضار لكل حصة: 1"], []),
))
R.append((7250013,
("Estofado de res con bolitas de masa", "Una versión más saludable de un platillo clásico, con verduras adicionales y una salsa espesa.", "6", "379 g",
 ["1 cucharadita de aceite de girasol", "500 g de carne de res magra, en cubos", "300 g de cebollas, picadas", "300 g de zanahorias, picadas", "1 tallo de apio (60 g), en rodajas", "250 g de champiñones, en rebanadas", "300 g de papas, en cubos", "1 cucharada de harina de trigo todo uso", "1 cubito de caldo bajo en sal (de res o de verduras) disuelto en 1.5 L de agua hirviendo", "200 g de harina integral", "1 cucharadita de polvo para hornear", "una buena pizca de pimienta blanca", "1 cucharadita de tomillo seco", "1 cucharada de perejil fresco picado", "100 ml de leche semidescremada", "1 cucharadita de aceite de oliva"],
 ["Precaliente el horno a 180 °C (gas 4). Ponga el aceite en una olla grande y, después de 2 a 3 minutos, agregue la carne. Revuelva 2 minutos y, una vez sellada la carne, agregue las cebollas, las zanahorias, el apio y los champiñones, y cocine de 3 a 4 minutos.", "Agregue las papas y espolvoree la harina sobre el platillo, cubriendo de manera uniforme la carne y las verduras.", "Vierta poco a poco el caldo, revolviendo constantemente. Cocine a fuego lento de 2 a 3 minutos, hasta que espese.", "Retire del fuego y pase a un recipiente para horno, tape y cocine en el horno 1¼ horas.", "Cuando el estofado lleve 1 hora cocinándose, prepare las bolitas de masa: Ponga la harina, el polvo para hornear, la pimienta, el tomillo y el perejil en un tazón, luego incorpore poco a poco la leche, mezclando bien hasta formar una masa suave. Para que la masa no se pegue, unte aceite de oliva en sus manos, luego forme seis bolas con la masa y reserve.", "Coloque las bolitas de masa sobre el estofado y cocine sin tapar de 15 a 20 minutos, hasta que estén cocidas, con una costra ligera, pero todavía suaves."],
 ["Haga este platillo clásico apto para vegetarianos sustituyendo la carne magra de res por un sustituto de carne, o simplemente agregando más verduras.", "Para reducir el contenido de carbohidratos de este platillo, pruebe a hacer bolitas de masa más pequeñas o déjelas fuera por completo.", "Porciones de fruta/verdura por porción: 1"], []),
("يخنة اللحم البقري مع كرات العجين", "نسخة أكثر صحة من طبق كلاسيكي، مع خضار إضافية ومرق غني.", "6", "379 غ",
 ["1 ملعقة صغيرة زيت دوار الشمس", "500 غ لحم بقري قليل الدهن، مقطع إلى مكعبات", "300 غ بصل، مفروم", "300 غ جزر، مفروم", "1 ساق كرفس (60 غ)، مقطعة إلى شرائح", "250 غ فطر، مقطع إلى شرائح", "300 غ بطاطس، مقطعة إلى مكعبات", "1 ملعقة كبيرة دقيق عادي", "1 مكعب مرق قليل الملح (لحم بقري أو خضار) مذاب في 1.5 لتر ماء مغلي", "200 غ دقيق القمح الكامل", "1 ملعقة صغيرة بيكنج باودر", "رشة كبيرة من الفلفل الأبيض", "1 ملعقة صغيرة زعتر مجفف", "1 ملعقة كبيرة بقدونس طازج مفروم", "100 مل حليب نصف خالي الدسم", "1 ملعقة صغيرة زيت زيتون"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (درجة الغاز 4). ضع الزيت في قدر كبير، وبعد 2-3 دقائق أضف اللحم. حرّك لمدة دقيقتين، وبعد أن يتماسك سطح اللحم أضف البصل والجزر والكرفس والفطر واطهها لمدة 3-4 دقائق.", "أضف البطاطس ورشّ الدقيق فوق الطبق بحيث يغطي اللحم والخضار بالتساوي.", "اسكب المرق تدريجيًا مع التحريك المستمر. اتركه على نار هادئة لمدة 2-3 دقائق حتى يتكاثف.", "ارفعه عن النار وانقله إلى طبق مقاوم للحرارة، وغطِّه واطهه في الفرن لمدة 1¼ ساعة.", "بعد أن تمضي ساعة على طهي اليخنة، حضّر كرات العجين: ضع الدقيق والبيكنج باودر والفلفل والزعتر والبقدونس في وعاء، ثم أضف الحليب تدريجيًا مع الخلط جيدًا لتكوين عجينة طرية. حتى لا تلتصق العجينة، ادهن يديك بزيت الزيتون، ثم شكّل العجينة إلى ست كرات وضعها جانبًا.", "ضع كرات العجين فوق اليخنة واطهها مكشوفة لمدة 15-20 دقيقة حتى تنضج بقشرة خفيفة، مع بقائها طرية."],
 ["اجعل هذا الطبق الكلاسيكي مناسبًا للنباتيين باستبدال اللحم البقري قليل الدهن ببديل اللحم، أو بإضافة المزيد من الخضار ببساطة.", "لتقليل محتوى الكربوهيدرات في هذا الطبق، جرّب صنع كرات عجين أصغر أو استغنِ عنها تمامًا.", "حصص الفاكهة/الخضار لكل حصة: 1"], []),
))
R.append((7252558,
("Col rizada salteada con chile, jengibre y ajo", "Este platillo de un verde vibrante se cocina rápido y va muy bien con comida china o con pescado, carne o pollo a la parrilla.", "4", "83 g",
 ["2 cucharaditas de aceite de colza", "3 cm de raíz de jengibre fresco, pelado y picado fino", "2 a 3 dientes de ajo, machacados", "una pizca de hojuelas de chile", "200 g de col rizada (kale), picada (sin los tallos gruesos)", "4 cucharadas de agua", "jugo de medio limón"],
 ["Ponga el aceite en una sartén a fuego bajo-medio y agregue el jengibre y el ajo, mezclando bien de 1 a 2 minutos.", "Ahora agregue las hojuelas de chile y revuelva otro minuto.", "Agregue la col rizada y mezcle bien de 2 a 3 minutos.", "Suba el fuego, agregue el agua, mezcle, tape la sartén y cocine otros 5 a 6 minutos, revolviendo de vez en cuando.", "Rocíe con el jugo de limón y sirva."],
 ["Los tallos de la col rizada son comestibles, pero tardan más en cocinarse que las hojas; si los quita y los pica finos primero, puede cocinarlos junto con las hojas.", "Pruebe a cocinar 200 g de col rizada con un poro picado y una manzana picada sin pelar, en muy poca agua.", "Porciones de fruta/verdura por porción: 0"], []),
("كرنب أجعد مقلي سريعًا بالفلفل الحار والزنجبيل والثوم", "هذا الطبق الأخضر النابض بالحياة سريع الطهي ويناسب الطعام الصيني أو السمك أو اللحم أو الدجاج المشوي.", "4", "83 غ",
 ["2 ملعقة صغيرة زيت اللفت (كانولا)", "3 سم جذر زنجبيل طازج، مقشر ومفروم ناعمًا", "2-3 فصوص ثوم، مهروسة", "رشة رقائق فلفل حار", "200 غ كرنب أجعد (كيل)، مفروم (مع إزالة السيقان السميكة)", "4 ملعقة كبيرة ماء", "عصير نصف ليمونة"],
 ["ضع الزيت في قدر على نار متوسطة إلى منخفضة، وأضف الزنجبيل والثوم وقلّبهما جيدًا لمدة 1-2 دقيقة.", "الآن أضف رقائق الفلفل الحار وحرّك دقيقة أخرى.", "أضف الكرنب وقلّبه جيدًا لمدة 2-3 دقائق.", "ارفع الحرارة وأضف الماء وحرّك، وضع الغطاء على القدر واطهه 5-6 دقائق أخرى مع التحريك من حين لآخر.", "رشّ عصير الليمون وقدّمه."],
 ["سيقان الكرنب صالحة للأكل لكنها تحتاج وقتًا أطول للطهي من الأوراق؛ فإذا أزلتها وفرمتها ناعمًا أولًا، فيمكنك طهيها مع الأوراق معًا.", "جرّب طهي 200 غ من الكرنب مع كراث مفروم وتفاحة مفرومة غير مقشرة في كمية قليلة جدًا من الماء.", "حصص الفاكهة/الخضار لكل حصة: 0"], []),
))
R.append((7253865,
("Sopa cremosa de pescados surtidos", "Una sopa reconfortante y sustanciosa que los amantes del marisco adorarán.", "6", "327 g",
 ["15 g de untable a base de aceite vegetal", "1 cebolla grande, picada", "1 hoja de laurel", "2 tallos de apio, en rodajas finas", "450 g de papas harinosas, en cubos", "25 g de coco rallado deshidratado", "600 ml de leche descremada", "600 ml de caldo de pescado", "450 g de filetes de pescado surtidos, sin espinas ni piel, en cubos", "100 g de camarones cocidos y pelados", "125 g de chícharos congelados", "125 g de granos de elote congelados", "3 cucharadas de perejil fresco, picado"],
 ["Derrita la mantequilla en una olla grande, agregue la cebolla, la hoja de laurel, el apio y las papas y fría de 3 a 4 minutos.", "Agregue el coco, la leche y el caldo de pescado, deje que hierva, tape y cocine a fuego lento de 20 a 25 minutos, hasta que las papas estén cocidas.", "Con un tenedor, aplaste la mayor parte de las papas y mezcle bien para integrar.", "Agregue a la olla el pescado, los camarones, los chícharos y el elote, y continúe cocinando a fuego lento otros 5 minutos o hasta que el pescado esté cocido.", "Sazone bien y sirva cubierta con el perejil."],
 ["Para agregar más verduras, simplemente saltee unos champiñones o calabacita picada y un pimiento rojo picado, y mezcle justo antes de servir.", "Dele un toque picante agregando 1 cucharada de pasta de curri suave junto con el caldo. Sirva espolvoreada con cilantro picado fino.", "Porciones de fruta/verdura por porción: 1"], []),
("شوربة السمك المشكّل الكريمية (تشاودر)", "حساء دافئ ومشبع سيعشقه محبّو المأكولات البحرية.", "6", "327 غ",
 ["15 غ دهن نباتي", "1 بصلة كبيرة، مفرومة", "1 ورقة غار", "2 ساق كرفس، مقطعة شرائح رفيعة", "450 غ بطاطس دقيقية القوام، مقطعة إلى مكعبات", "25 غ جوز هند مجفف مبشور", "600 مل حليب خالي الدسم", "600 مل مرق سمك", "450 غ فيليه سمك مشكّل منزوع العظم والجلد، مقطع إلى مكعبات", "100 غ روبيان مطبوخ ومقشر", "125 غ بازلاء مجمدة", "125 غ حبوب ذرة حلوة مجمدة", "3 ملعقة كبيرة بقدونس طازج، مفروم"],
 ["ذوّب الدهن في قدر كبير، وأضف البصل وورقة الغار والكرفس والبطاطس وقلّبها لمدة 3-4 دقائق.", "أضف جوز الهند والحليب ومرق السمك، واتركه يغلي، وغطِّه واتركه على نار هادئة لمدة 20-25 دقيقة حتى تنضج البطاطس.", "باستخدام شوكة، اهرس معظم البطاطس وحرّك جيدًا لتمتزج.", "أضف السمك والروبيان والبازلاء والذرة إلى القدر وتابع الطهي على نار هادئة 5 دقائق أخرى أو حتى ينضج السمك.", "تبّل جيدًا وقدّمه مزينًا بالبقدونس."],
 ["لإضافة خضار أخرى، قلّب ببساطة بعض الفطر أو الكوسا المفرومة وفلفلًا رومي أحمر مفرومًا، وأضفها قبل التقديم مباشرة.", "أضف حرارة إلى الطبق بإضافة 1 ملعقة كبيرة من معجون الكاري المعتدل مع المرق. قدّمه مع رشة من الكزبرة المفرومة ناعمًا.", "حصص الفاكهة/الخضار لكل حصة: 1"], []),
))
build(4, R)
